// Filter to .py files only, cap count so we don't fetch hundreds of files
// in a large repo -- fine for this hackathon's ~15-file demo app, revisit
// if the demo repo grows.
const tree = $json.tree || [];
const pyFiles = tree.filter((t) => t.type === 'blob' && t.path.endsWith('.py')).slice(0, 100);
return pyFiles.map((f) => ({ json: { path: f.path, blob_sha: f.sha } }));

// Regex-match import statements for the target package. Deliberately
// simple string matching (PRD: "simple string/import match is fine for
// MVP") -- covers `import X`, `import X as y`, `from X import ...`,
// `from X.sub import ...`. Skips docstrings/comments -- see
// search_symbol_usage.json's header comment for why that skip exists
// (found by testing against the real demo repo, not theoretical).
const pkg = $('When called as a tool').first().json.package;
const escaped = pkg.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const importRe = new RegExp(`^\\s*(import\\s+${escaped}\\b|from\\s+${escaped}(\\.[\\w.]+)?\\s+import\\b)`);

const results = [];
for (const item of $input.all()) {
  const path = item.json.path || (item.json.__path || '');
  const content = typeof item.json === 'string' ? item.json : (item.json.data || item.json.body || '');
  // n8n's HTTP Request node puts plain-text bodies in different fields
  // depending on version -- if this comes back empty, check the actual
  // output shape in the editor and adjust the field name above.
  const lines = String(content).split('\n');
  let inDocstring = false;
  lines.forEach((rawLine, i) => {
    const trimmed = rawLine.trim();
    const wasInDocstring = inDocstring;
    const tripleQuoteCount = (trimmed.match(/"""|'''/g) || []).length;
    const isOneLineDocstring = tripleQuoteCount >= 2 && (trimmed.startsWith('"""') || trimmed.startsWith("'''"));
    if (tripleQuoteCount % 2 === 1) inDocstring = !inDocstring;
    if (wasInDocstring || isOneLineDocstring || trimmed.startsWith('#')) return;
    if (importRe.test(rawLine)) {
      results.push({ file: path, line: i + 1, statement: trimmed });
    }
  });
}
return [{ json: { package: pkg, matches: results } }];
